  const assigned = await tools.assign({ repo, number: issue.number, assignee: issue.user.login });
  if (assigned.number !== issue.number || assigned.assignee.login !== issue.user.login) throw new Error(`Unexpected assignment for #${issue.number}`);
}));
return { candidates: targets.length, errors: outcomes.flatMap((outcome, index) => outcome.status === 'rejected' ? [{ number: targets[index].number, error: String(outcome.reason) }] : []) };","answer":""}

